SourceCode.Declaration:
/// <summary>
/// Deletes batch monitoring log records per operation type based on the
/// DaysToKeepLog value configured in METBatchMonitoringLogParameters.
/// Running records are never deleted.
/// </summary>
public class METBatchMonitoringClearLog extends RunBaseBatch implements BatchRetryable
{
    QueryRun    queryRun;

}

Method.Source:
public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    qbds = query.addDataSource(tablenum(METBatchMonitoringLogParameters));
    QueryBuildRange         qBR;
    ;
    qBR = SysQuery::findOrCreateRange(qbds, fieldnum(METBatchMonitoringLogParameters, DaysToKeepLog));
    qBR.value(SysQuery::range(1, maxInt()));
    qBR.status(RangeStatus::Locked);

    queryRun = new QueryRun(query);
}

public void run()
{
    METBatchMonitoringLogParameters params;
    METBatchMonitoringLog           log;
    TransDateTime                   cutoffDateTime;
    int                             deletedCount;
    int                             operationCount;

    while (queryRun.next())
    {
        params = queryRun.get(tablenum(METBatchMonitoringLogParameters));

        cutoffDateTime = DateTimeUtil::addDays(DateTimeUtil::utcNow(), -params.DaysToKeepLog);

        // Convert stale Running records (dead session) to Failed so they are included in the delete below.
        while select log
            where log.Operation      == params.LogOperation
               && log.createdDateTime < cutoffDateTime
               && log.Status         == METBatchMonitoringStatus::Running
        {
            if (!log.isSessionActive())
            {
                log.skipTTSCheck(true);
                log.selectForUpdate(true);
                log.Status              = METBatchMonitoringStatus::Failed;
                log.EndDateTime         = DateTimeUtil::utcNow();
                log.LastUpdatedDateTime = log.EndDateTime;
                log.update();
            }
        }

        select count(RecId) from log
            where log.Operation      == params.LogOperation
               && log.createdDateTime < cutoffDateTime
               && log.Status         != METBatchMonitoringStatus::Running;
        operationCount = any2int(log.RecId);

        if (operationCount > 0)
        {
            delete_from log
                where log.Operation      == params.LogOperation
                   && log.createdDateTime < cutoffDateTime
                   && log.Status         != METBatchMonitoringStatus::Running;

            deletedCount += operationCount;
        }
    }

    info(strFmt("@MET:METBatchMonitoringClearLogResult", deletedCount));
}

public static METBatchMonitoringClearLog construct()
{
    return new METBatchMonitoringClearLog();
}

public static void main(Args _args)
{
    METBatchMonitoringClearLog runObject = METBatchMonitoringClearLog::construct();
    ;
    if (runObject.prompt())
    {
        runObject.runOperation();
    }
}
